  function departmentPrograms(d){
    const map={
      'Computer Science':[{name:'B.Sc. Computer Science',courses:14,learners:340},{name:'M.Sc. Data Science',courses:14,learners:62}],
      'Engineering':[{name:'B.Eng. Systems',courses:12,learners:188},{name:'B.Eng. Electrical',courses:6,learners:78},{name:'M.Eng. Sustainable Design',courses:4,learners:52}],
      'Business Foundations':[{name:'BBA Business Administration',courses:8,learners:192},{name:'Foundation Business Year',courses:6,learners:94}]
    };
    return map[d.name]||[{name:`${d.name} Program A`,courses:Math.ceil(d.courses/2),learners:Math.ceil(d.learners*.62)},{name:`${d.name} Program B`,courses:Math.floor(d.courses/2),learners:Math.floor(d.learners*.38)}];
  }

